local all_frames = { frame1_grid, frame2_grid, frame3_grid, frame4_grid }

local function renderGrid(img, gridData, pal)
    for y = 1, #gridData do
        local line = gridData[y]
        for x = 1, #line do
            local char = line:sub(x, x)
            local hex = pal[char]
            if hex then
                local h = hex:gsub("#", "")
                local r = tonumber(h:sub(1, 2), 16) or 0
                local g = tonumber(h:sub(3, 4), 16) or 0
                local b = tonumber(h:sub(5, 6), 16) or 0
                local a = (char == "S") and 130 or 255
                img:drawPixel(x - 1, y - 1, Color{ r = r, g = g, b = b, a = a })
            else
                img:drawPixel(x - 1, y - 1, Color{ r = 0, g = 0, b = 0, a = 0 })
            end
        end
    end
end

for i = 1, #all_frames do
    if i > 1 then
        sprite:newFrame()
        sprite.frames[i].duration = frameDuration
    end
    local curImage = layer:cel(i).image
    renderGrid(curImage, all_frames[i], PALETTE)
end

-- Export files via CLI
sprite:saveCopyAs("output/aseprite/swaying_bush_berries_48.aseprite")
if #sprite.frames > 1 then
    sprite:saveCopyAs("output/gif/swaying_bush_berries_48.gif")
    local totalFrames = #sprite.frames
    local sheetSprite = Sprite(width * totalFrames, height, ColorMode.RGB)
    local sheetImage = sheetSprite.cels[1].image
    for i = 1, totalFrames do
        local frameCel = layer:cel(i)
        if frameCel then
            sheetImage:drawImage(frameCel.image, Point((i - 1) * width, 0))
        end
    end
    sheetSprite:saveCopyAs("output/Sheet/swaying_bush_berries_48_sheet.png")
    sheetSprite:close()
else
    sprite:saveCopyAs("output/Sheet/swaying_bush_berries_48.png")
end
